export const HANGUL_BASE = 0xac00;
export const HANGUL_END = 0xd7a3;
let table: Uint8Array | null = null;
export function hangulGlyph(code: number): Uint8Array | null {
  if (code < HANGUL_BASE || code > HANGUL_END) return null;
  if (!table) {
    const bin = atob(B64);
    table = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) table[i] = bin.charCodeAt(i);
  }
  const off = (code - HANGUL_BASE) * 8;
  return table.subarray(off, off + 8);
}
